screenPanels.initJs:
function(container, apiUrl, tables) {
  const historyTable = tables[0]; // 判定ロジック適用履歴テーブル
  const caseIdInput = container.querySelector('[data-testid="case-id-input"]');
  const appraiserNameInput = container.querySelector('[data-testid="appraiser-name-input"]');
  const logicNameInput = container.querySelector('[data-testid="logic-name-input"]');
  const dateFromInput = container.querySelector('[data-testid="date-from-input"]');
  const dateToInput = container.querySelector('[data-testid="date-to-input"]');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');
  const workTypeFilter = container.querySelector('[data-testid="work-type-filter"]');
  const priceBandFilter = container.querySelector('[data-testid="price-band-filter"]');
  const deviationFromInput = container.querySelector('[data-testid="deviation-from-input"]');
  const deviationToInput = container.querySelector('[data-testid="deviation-to-input"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const historyTbody = container.querySelector('#history-tbody');
  const resultCount = container.querySelector('[data-testid="result-count"]');
  const detailPanel = container.querySelector('#detail-panel');
  const closeDetailBtn = container.querySelector('#close-detail-btn');

  let allRecords = [];

  // 初期データ読み込み
  async function loadData() {
    const records = await window.aivicApi.list(0); // テーブルインデックス 0
    if (records) {
      allRecords = records;
      renderTable(allRecords);
    }
  }

  // テーブル描画
  function renderTable(records) {
    historyTbody.innerHTML = '';
    records.forEach((record, idx) => {
      const row = document.createElement('tr');
      row.style.cssText = `
        cursor: pointer;
        border-bottom: 1px solid var(--border);
        transition: background-color 0.15s;
      `;
      row.onmouseover = () => row.style.background = 'rgba(74, 85, 104, 0.05)';
      row.onmouseout = () => row.style.background = 'transparent';
      row.onclick = () => showDetail(record);

      const appliedAt = record['適用日時'] ? new Date(record['適用日時']).toLocaleString('ja-JP') : '-';
      const caseId = record['査定案件ID'] || '-';
      const logicName = record['ロジック名'] || '-';
      const status = record['適用ステータス'] || '-';
      const resultSummary = (record['適用結果'] || '-').substring(0, 30);

      row.innerHTML = `
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${appliedAt}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-family: monospace; font-size: 12px;">${caseId}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${logicName}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">
          <span style="
            padding: 2px 6px;
            border-radius: 3px;
            font-size: 11px;
            font-weight: 500;
            background: ${status === '成功' ? 'rgba(76, 175, 80, 0.15)' : status === '失敗' ? 'rgba(244, 67, 54, 0.15)' : 'rgba(255, 152, 0, 0.15)'};
            color: ${status === '成功' ? '#2e7d32' : status === '失敗' ? '#c62828' : '#e65100'};
          ">${status}</span>
        </td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${resultSummary}${resultSummary.length > 30 ? '...' : ''}</td>
      `;
      historyTbody.appendChild(row);
    });
    resultCount.textContent = records.length;
  }

  // 詳細パネル表示
  function showDetail(record) {
    container.querySelector('#detail-applied-at').textContent = record['適用日時'] ? new Date(record['適用日時']).toLocaleString('ja-JP') : '-';
    container.querySelector('#detail-case-id').textContent = record['査定案件ID'] || '-';
    container.querySelector('#detail-logic-name').textContent = record['ロジック名'] || '-';
    container.querySelector('#detail-status').textContent = record['適用ステータス'] || '-';
    container.querySelector('#detail-auto-flag').textContent = record['自動適用フラグ'] ? 'はい' : 'いいえ';
    container.querySelector('#detail-result').textContent = record['適用結果'] || '-';
    container.querySelector('#detail-error').textContent = record['エラーメッセージ'] || '（なし）';
    container.querySelector('#detail-appraiser-id').textContent = record['査定員ID'] || '-';
    container.querySelector('#detail-created-at').textContent = record['作成日時'] ? new Date(record['作成日時']).toLocaleString('ja-JP') : '-';

    detailPanel.style.display = 'flex';

    // 案件詳細へボタン
    container.querySelector('#view-case-btn').onclick = () => {
      if (record['査定案件ID']) {
        window.showScreen('scr-1783331075653'); // 参照データ検索画面
      }
    };

    // ロジック確認ボタン
    container.querySelector('#view-logic-btn').onclick = () => {
      window.showScreen('scr-1783331123576'); // 判定基準管理画面
    };
  }

  // 詳細パネル閉じる
  closeDetailBtn.onclick = () => {
    detailPanel.style.display = 'none';
  };

  // 検索フィルタ適用
  function applyFilters() {
    const caseId = caseIdInput.value.toLowerCase();
    const appraiserName = appraiserNameInput.value.toLowerCase();
    const logicName = logicNameInput.value.toLowerCase();
    const dateFrom = dateFromInput.value ? new Date(dateFromInput.value) : null;
    const dateTo = dateToInput.value ? new Date(dateToInput.value) : null;
    const status = statusFilter.value;
    const workType = workTypeFilter.value;
    const priceBand = priceBandFilter.value;
    const devFrom = deviationFromInput.value ? parseFloat(deviationFromInput.value) : null;
    const devTo = deviationToInput.value ? parseFloat(deviationToInput.value) : null;

    const filtered = allRecords.filter(record => {
      if (caseId && !(record['査定案件ID'] || '').toLowerCase().includes(caseId)) return false;
      if (appraiserName && !(record['査定員名'] || '').toLowerCase().includes(appraiserName)) return false;
      if (logicName && !(record['ロジック名'] || '').toLowerCase().includes(logicName)) return false;
      if (status && record['適用ステータス'] !== status) return false;
      if (workType && record['工種'] !== workType) return false;
      if (priceBand && record['金額帯'] !== priceBand) return false;

      if (dateFrom || dateTo) {
        const recordDate = record['適用日時'] ? new Date(record['適用日時']) : null;
        if (recordDate) {
          if (dateFrom && recordDate < dateFrom) return false;
          if (dateTo) {
            const dateToEnd = new Date(dateTo);
            dateToEnd.setHours(23, 59, 59, 999);
            if (recordDate > dateToEnd) return false;
          }
        }
      }

      if (devFrom !== null || devTo !== null) {
        const deviation = record['相場乖離率'] ? parseFloat(record['相場乖離率']) : null;
        if (deviation !== null) {
          if (devFrom !== null && deviation < devFrom) return false;
          if (devTo !== null && deviation > devTo) return false;
        }
      }

      return true;
    });

    renderTable(filtered);
  }

  // リセット
  resetBtn.onclick = () => {
    caseIdInput.value = '';
    appraiserNameInput.value = '';
    logicNameInput.value = '';
    dateFromInput.value = '';
    dateToInput.value = '';
    statusFilter.value = '';
    workTypeFilter.value = '';
    priceBandFilter.value = '';
    deviationFromInput.value = '';
    deviationToInput.value = '';
    renderTable(allRecords);
    detailPanel.style.display = 'none';
  };

  // 検索
  searchBtn.onclick = applyFilters;

  // CSVエクスポート
  exportBtn.onclick = () => {
    const rows = container.querySelectorAll('#history-tbody tr');
    const headers = ['適用日時', '査定案件ID', 'ロジック名', '適用ステータス', '適用結果', 'エラーメッセージ', '自動適用フラグ', '作成日時'];
    const csvContent = [
      '\uFEFF' + headers.map(h => `"${h}"`).join(','),
      ...allRecords.map(record =>
        headers.map(h => {
          const val = record[h] || '';
          return `"${String(val).replace(/"/g, '""')}"`;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `判定ロジック適用履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const monthlyResultIdx = tables.findIndex(t => t.tableName === '月次集計結果');
  const assessorIdx = tables.findIndex(t => t.tableName === '査定員');
  const workTypeIdx = tables.findIndex(t => t.tableName === '工種マスタ');

  // DOM 要素の取得
  const monthInput = container.querySelector('[data-testid="month-filter"]');
  const assessorSelect = container.querySelector('[data-testid="assessor-filter"]');
  const workTypeSelect = container.querySelector('[data-testid="worktype-filter"]');
  const priceRangeSelect = container.querySelector('[data-testid="pricerange-filter"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const refreshBtn = container.querySelector('[data-testid="refresh-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const monthlyTbody = container.querySelector('#monthly-tbody');
  const assessorTbody = container.querySelector('#assessor-tbody');
  const workTypeTbody = container.querySelector('#worktype-tbody');

  // KPI 要素
  const kpiCaseCount = container.querySelector('[data-testid="kpi-case-count"]');
  const kpiCaseTrend = container.querySelector('[data-testid="kpi-case-trend"]');
  const kpiAccuracy = container.querySelector('[data-testid="kpi-accuracy"]');
  const kpiDeviation = container.querySelector('[data-testid="kpi-deviation"]');
  const kpiVariance = container.querySelector('[data-testid="kpi-variance"]');
  const kpiStandardization = container.querySelector('[data-testid="kpi-standardization"]');

  // ナビゲーションボタン
  const detailAnalysisBtn = container.querySelector('[data-testid="detail-analysis-button"]');
  const varianceAnalysisBtn = container.querySelector('[data-testid="variance-analysis-button"]');
  const logicHistoryBtn = container.querySelector('[data-testid="logic-history-button"]');
  const accuracyMetricsBtn = container.querySelector('[data-testid="accuracy-metrics-button"]');

  // 初期月を今月に設定
  const today = new Date();
  const currentMonth = today.toISOString().slice(0, 7);
  monthInput.value = currentMonth;

  // データ取得・表示関数
  async function loadData() {
    if (monthlyResultIdx === -1) {
      console.warn('月次集計結果テーブルが見つかりません');
      return;
    }

    try {
      const allResults = await window.aivicApi.list(monthlyResultIdx);
      if (!allResults) return;

      // フィルタ条件の取得
      const selectedMonth = monthInput.value;
      const selectedAssessor = assessorSelect.value;
      const selectedWorkType = workTypeSelect.value;
      const selectedPriceRange = priceRangeSelect.value;

      // フィルタリング
      let filtered = allResults.filter(r => {
        const monthMatch = !selectedMonth || r.集計年月 === selectedMonth;
        const assessorMatch = !selectedAssessor || r.査定員ID === selectedAssessor;
        const workTypeMatch = !selectedWorkType || r.工種ID === selectedWorkType;
        const priceRangeMatch = !selectedPriceRange || r.金額帯ID === selectedPriceRange;
        return monthMatch && assessorMatch && workTypeMatch && priceRangeMatch;
      });

      // 月次推移テーブル表示（全体集計のみ）
      const overallResults = filtered.filter(r => !r.査定員ID && !r.工種ID && !r.金額帯ID);
      renderMonthlyTable(overallResults);

      // KPI 更新
      if (overallResults.length > 0) {
        const latest = overallResults[overallResults.length - 1];
        kpiCaseCount.textContent = latest.査定案件数 || '-';
        kpiAccuracy.textContent = (latest.平均判定精度 || '-') + '%';
        kpiDeviation.textContent = (latest.相場乖離率 || '-') + '%';
        kpiVariance.textContent = latest.判定ばらつき指数 || '-';
        kpiStandardization.textContent = (latest.標準化達成度 || '-') + '%';

        // 前月比計算（簡易版）
        if (overallResults.length > 1) {
          const prev = overallResults[overallResults.length - 2];
          const trend = ((latest.査定案件数 - prev.査定案件数) / prev.査定案件数 * 100).toFixed(1);
          kpiCaseTrend.textContent = (trend > 0 ? '+' : '') + trend + '%';
        }
      }

      // 査定員別パフォーマンス（査定員IDが指定されている集計）
      const assessorResults = filtered.filter(r => r.査定員ID && !r.工種ID && !r.金額帯ID);
      renderAssessorTable(assessorResults);

      // 工種別集計（工種IDが指定されている集計）
      const workTypeResults = filtered.filter(r => !r.査定員ID && r.工種ID && !r.金額帯ID);
      renderWorkTypeTable(workTypeResults);

    } catch (error) {
      console.error('データ読込エラー:', error);
    }
  }

  function renderMonthlyTable(results) {
    if (results.length === 0) {
      monthlyTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="7" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">データなし</td></tr>';
      return;
    }

    monthlyTbody.innerHTML = results.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${r.集計年月 || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.査定案件数 || 0}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.平均判定精度 || '-'}%</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.相場乖離率 || '-'}%</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.判定ばらつき指数 || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.標準化達成度 || '-'}%</td>
        <td style="padding: 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 600; background: var(--primary); color: #fff;">
            ${r.集計ステータス === '確定' ? '確定' : r.集計ステータス === '仮集計' ? '仮' : '再'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  function renderAssessorTable(results) {
    if (results.length === 0) {
      assessorTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="4" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">データなし</td></tr>';
      return;
    }

    assessorTbody.innerHTML = results.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${r.査定員ID || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.査定案件数 || 0}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.平均判定精度 || '-'}%</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.相場乖離率 || '-'}%</td>
      </tr>
    `).join('');
  }

  function renderWorkTypeTable(results) {
    if (results.length === 0) {
      workTypeTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="4" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">データなし</td></tr>';
      return;
    }

    workTypeTbody.innerHTML = results.map(r => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${r.工種ID || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.査定案件数 || 0}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.平均判定精度 || '-'}%</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${r.相場乖離率 || '-'}%</td>
      </tr>
    `).join('');
  }

  // CSV エクスポート
  exportBtn.addEventListener('click', async () => {
    if (monthlyResultIdx === -1) return;
    try {
      const allResults = await window.aivicApi.list(monthlyResultIdx);
      if (!allResults || allResults.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['集計年月', '査定員ID', '工種ID', '金額帯ID', '査定案件数', '平均判定精度', '相場乖離率', '判定ばらつき指数', '標準化達成度', '不一致案件数', '乖離パターン件数', '改善指摘事項数', '前月比精度向上率', '集計ステータス', '備考'];
      const rows = allResults.map(r => [
        r.集計年月 || '',
        r.査定員ID || '',
        r.工種ID || '',
        r.金額帯ID || '',
        r.査定案件数 || '',
        r.平均判定精度 || '',
        r.相場乖離率 || '',
        r.判定ばらつき指数 || '',
        r.標準化達成度 || '',
        r.不一致案件数 || '',
        r.乖離パターン件数 || '',
        r.改善指摘事項数 || '',
        r.前月比精度向上率 || '',
        r.集計ステータス || '',
        r.備考 || ''
      ]);

      const csv = '\uFEFF' + [headers, ...rows].map(row => row.map(cell => {
        const str = String(cell || '');
        return str.includes(',') || str.includes('"') || str.includes('\n') ? `"${str.replace(/"/g, '""')}"` : str;
      }).join(',')).join('\n');

      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `月次集計結果_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    } catch (error) {
      console.error('CSV エクスポートエラー:', error);
    }
  });

  // 検索ボタン
  searchBtn.addEventListener('click', loadData);

  // 更新ボタン
  refreshBtn.addEventListener('click', loadData);

  // ナビゲーション
  detailAnalysisBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330941502');
  });

  varianceAnalysisBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330955923');
  });

  logicHistoryBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330970321');
  });

  accuracyMetricsBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330986886');
  });

  // 初期ロード
  loadData();
}

function(container, apiUrl, tables) {
  const judgmentTbody = container.querySelector('#judgment-tbody');
  const deviationTbody = container.querySelector('#deviation-tbody');
  const saveDialog = container.querySelector('#save-dialog');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  const cancelSaveBtn = container.querySelector('[data-testid="cancel-save"]');
  const confirmSaveBtn = container.querySelector('[data-testid="confirm-save"]');
  const caseIdInput = container.querySelector('[data-testid="case-id-search"]');
  const assessorSelect = container.querySelector('[data-testid="assessor-select"]');
  const statusSelect = container.querySelector('[data-testid="status-select"]');
  const varianceChart = container.querySelector('#variance-chart');

  let allJudgments = [];
  let allDeviations = [];
  let selectedJudgmentId = null;

  // 初期データロード
  async function loadData() {
    try {
      const judgments = await window.aivicApi.list(2); // 査定判定結果
      const deviations = await window.aivicApi.list(6); // 相場乖離分析
      const variances = await window.aivicApi.list(7); // 判定ばらつき分析
      const accuracy = await window.aivicApi.list(8); // 判定精度指標
      const patterns = await window.aivicApi.list(10); // 乖離パターン履歴

      allJudgments = judgments || [];
      allDeviations = deviations || [];

      renderJudgments(allJudgments);
      renderDeviations(patterns || []);
      updateMetrics(allJudgments, allDeviations, accuracy || []);
      drawVarianceChart(variances || []);
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  function renderJudgments(data) {
    if (!data || data.length === 0) {
      judgmentTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="7" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">データなし</td></tr>';
      return;
    }
    judgmentTbody.innerHTML = data.map(row => `
      <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border); cursor: pointer;" onclick="this.style.background='var(--bg-sidebar)'">
        <td style="padding: 8px; border-right: 1px solid var(--border);">${row.caseId || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">${row.itemName || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">${row.assessorName || '-'}</td>
        <td style="padding: 8px; text-align: right; border-right: 1px solid var(--border);">¥${(row.assessmentAmount || 0).toLocaleString()}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">${row.judgmentResult || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 2px; font-size: 10px; background: ${row.status === '保存済' ? 'rgba(74, 85, 104, 0.1)' : 'rgba(255, 193, 7, 0.1)'}; color: ${row.status === '保存済' ? 'var(--primary)' : '#f57c00'};">
            ${row.status || '未保存'}
          </span>
        </td>
        <td style="padding: 8px; text-align: center;">
          <button class="detail-btn" data-id="${row.id}" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 2px; font-size: 10px; cursor: pointer;">詳細</button>
        </td>
      </tr>
    `).join('');

    container.querySelectorAll('.detail-btn').forEach(btn => {
      btn.onclick = (e) => {
        e.stopPropagation();
        selectedJudgmentId = btn.dataset.id;
        showLogicDetail(allJudgments.find(j => j.id === selectedJudgmentId));
      };
    });
  }

  function renderDeviations(data) {
    if (!data || data.length === 0) {
      deviationTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">データなし</td></tr>';
      return;
    }
    deviationTbody.innerHTML = data.slice(0, 5).map(row => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 8px; border-right: 1px solid var(--border);">${new Date(row.detectionDate).toLocaleString('ja-JP')}</td>
        <td style="padding: 6px 8px; border-right: 1px solid var(--border);">${row.patternClass || '-'}</td>
        <td style="padding: 6px 8px; text-align: right; border-right: 1px solid var(--border);">${row.deviationRate || '-'}%</td>
        <td style="padding: 6px 8px; border-right: 1px solid var(--border);">${row.deviationDirection || '-'}</td>
        <td style="padding: 6px 8px;">${row.reason || '-'}</td>
      </tr>
    `).join('');
  }

  function showLogicDetail(judgment) {
    const detail = container.querySelector('#logic-detail');
    if (!judgment) {
      detail.innerHTML = '<p style="margin: 0;">データなし</p>';
      return;
    }
    detail.innerHTML = `
      <div style="font-size: 12px;">
        <p style="margin: 0 0 4px 0;"><strong>案件ID:</strong> ${judgment.caseId || '-'}</p>
        <p style="margin: 0 0 4px 0;"><strong>適用ロジック:</strong> ${judgment.logicName || '-'}</p>
        <p style="margin: 0 0 4px 0;"><strong>判定基準:</strong> ${judgment.logicDescription || '-'}</p>
        <p style="margin: 0 0 4px 0;"><strong>判定理由:</strong> ${judgment.reason || '-'}</p>
        <p style="margin: 0;"><strong>標準化準拠:</strong> ${judgment.standardCompliant ? '○' : '×'}</p>
      </div>
    `;
  }

  function updateMetrics(judgments, deviations, accuracy) {
    if (deviations.length > 0) {
      const rates = deviations.map(d => parseFloat(d.deviationRate) || 0);
      const avg = (rates.reduce((a, b) => a + b, 0) / rates.length).toFixed(1);
      const max = Math.max(...rates).toFixed(1);
      container.querySelector('[data-testid="avg-deviation"]').textContent = avg + '%';
      container.querySelector('[data-testid="max-deviation"]').textContent = max + '%';
      container.querySelector('[data-testid="review-count"]').textContent = deviations.filter(d => d.qualityJudgment === '要確認').length;
    }
    if (accuracy.length > 0) {
      const acc = accuracy[0];
      container.querySelector('[data-testid="accuracy-rate"]').textContent = acc.accuracyRate || '-';
      container.querySelector('[data-testid="total-judgments"]').textContent = acc.totalJudgments || '-';
      container.querySelector('[data-testid="avg-deviation-rate"]').textContent = acc.avgDeviationRate || '-';
      container.querySelector('[data-testid="variance-degree"]').textContent = acc.varianceDegree || '-';
    }
    if (judgments.length > 0) {
      const lastSaved = judgments.filter(j => j.status === '保存済').sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt))[0];
      if (lastSaved) {
        container.querySelector('[data-testid="last-saved"]').textContent = new Date(lastSaved.updatedAt).toLocaleString('ja-JP');
        container.querySelector('[data-testid="saved-by"]').textContent = lastSaved.updatedBy || '-';
      }
    }
  }

  function drawVarianceChart(variances) {
    const ctx = varianceChart.getContext('2d');
    const levels = ['正常', '軽微', '要注意', '要改善'];
    const counts = levels.map(l => variances.filter(v => v.varianceLevel === l).length);
    const colors = ['#4a5568', '#90caf9', '#ffa726', '#ef5350'];

    ctx.clearRect(0, 0, varianceChart.width, varianceChart.height);
    const barWidth = varianceChart.width / levels.length;
    const maxCount = Math.max(...counts, 1);

    levels.forEach((level, i) => {
      const height = (counts[i] / maxCount) * (varianceChart.height - 40);
      ctx.fillStyle = colors[i];
      ctx.fillRect(i * barWidth + 10, varianceChart.height - height - 20, barWidth - 20, height);
      ctx.fillStyle = '#1a202c';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(level, i * barWidth + barWidth / 2, varianceChart.height - 5);
      ctx.fillText(counts[i], i * barWidth + barWidth / 2, varianceChart.height - height - 25);
    });
  }

  // イベントリスナー
  searchBtn.onclick = () => {
    const caseId = caseIdInput.value.trim();
    const assessor = assessorSelect.value;
    const status = statusSelect.value;
    const filtered = allJudgments.filter(j =>
      (!caseId || j.caseId?.includes(caseId)) &&
      (!assessor || j.assessorId === assessor) &&
      (!status || j.status === status)
    );
    renderJudgments(filtered);
  };

  exportBtn.onclick = () => {
    const csv = ['案件ID,品名,査定員,査定額,判定結果,ステータス,判定日時'];
    allJudgments.forEach(j => {
      csv.push(`"${j.caseId}","${j.itemName}","${j.assessorName}",${j.assessmentAmount},"${j.judgmentResult}","${j.status}","${j.judgmentDate}"`);
    });
    const blob = new Blob(['\uFEFF' + csv.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'judgment_records.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  saveBtn.onclick = () => {
    saveDialog.style.display = 'flex';
  };

  cancelSaveBtn.onclick = () => {
    saveDialog.style.display = 'none';
  };

  confirmSaveBtn.onclick = async () => {
    try {
      const toSave = allJudgments.filter(j => j.status !== '保存済');
      for (const j of toSave) {
        await window.aivicApi.update(2, j.id, { status: '保存済', updatedAt: new Date().toISOString(), updatedBy: 'current_user' });
      }
      saveDialog.style.display = 'none';
      loadData();
    } catch (e) {
      console.error('Save error:', e);
    }
  };

  // Escキーでダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && saveDialog.style.display !== 'none') {
      saveDialog.style.display = 'none';
    }
  });

  // overlay背景クリックで閉じる
  saveDialog.onclick = (e) => {
    if (e.target === saveDialog) {
      saveDialog.style.display = 'none';
    }
  };

  loadData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#proposal-tbody');
  const detailPanel = container.querySelector('#detail-panel');
  const noSelection = container.querySelector('#no-selection');
  const emptyMessage = container.querySelector('#empty-message');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');
  const priorityFilter = container.querySelector('[data-testid="priority-filter"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const refreshBtn = container.querySelector('[data-testid="refresh-button"]');
  const bulkApproveBtn = container.querySelector('#bulk-approve-btn');
  const bulkRejectBtn = container.querySelector('#bulk-reject-btn');
  const saveDetailBtn = container.querySelector('#save-detail-btn');
  const cancelDetailBtn = container.querySelector('#cancel-detail-btn');
  const confirmDialog = container.querySelector('#confirm-dialog');
  const confirmCancel = container.querySelector('#confirm-cancel');
  const confirmOk = container.querySelector('#confirm-ok');

  let allProposals = [];
  let currentSelectedId = null;
  let selectedForBulk = new Set();
  let pendingAction = null;

  // ダイアログ閉じる
  function closeDialog() {
    confirmDialog.style.display = 'none';
  }

  confirmCancel.addEventListener('click', closeDialog);
  confirmDialog.addEventListener('click', (e) => {
    if (e.target === confirmDialog) closeDialog();
  });

  // 確認ダイアログ表示
  function showConfirm(title, message, callback) {
    container.querySelector('#confirm-title').textContent = title;
    container.querySelector('#confirm-message').textContent = message;
    pendingAction = callback;
    confirmDialog.style.display = 'flex';
  }

  confirmOk.addEventListener('click', () => {
    if (pendingAction) pendingAction();
    closeDialog();
  });

  // データ取得
  async function loadProposals() {
    const proposals = await window.aivicApi.list(0); // tableIndex 0: 改善提案テーブル
    if (!proposals) return;
    allProposals = proposals;
    applyFiltersAndRender();
  }

  // フィルタ適用・レンダリング
  function applyFiltersAndRender() {
    const statusVal = statusFilter.value;
    const priorityVal = priorityFilter.value;

    let filtered = allProposals;
    if (statusVal) filtered = filtered.filter(p => p.approval_status === statusVal);
    if (priorityVal) filtered = filtered.filter(p => p.priority === priorityVal);

    tbody.innerHTML = '';
    if (filtered.length === 0) {
      emptyMessage.style.display = 'block';
      return;
    }
    emptyMessage.style.display = 'none';

    filtered.forEach(proposal => {
      const row = document.createElement('tr');
      row.dataset.id = proposal.id;
      row.style.borderBottom = '1px solid var(--border)';
      row.style.cursor = 'pointer';
      row.style.backgroundColor = selectedForBulk.has(proposal.id) ? 'rgba(74, 85, 104, 0.1)' : 'transparent';

      const priorityColor = proposal.priority === 'high' ? '#d32f2f' : proposal.priority === 'medium' ? '#f57c00' : '#1976d2';
      const statusBg = proposal.approval_status === 'approved' ? '#4caf50' : proposal.approval_status === 'rejected' ? '#f44336' : proposal.approval_status === 'in_review' ? '#ff9800' : '#9e9e9e';

      row.innerHTML = `
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text);">${proposal.proposal_id || '-'}</td>
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text);">${proposal.proposer_name || '-'}</td>
        <td style="padding: 10px 12px; font-size: 12px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 150px;">${proposal.proposal_content || '-'}</td>
        <td style="padding: 10px 12px; text-align: center; font-size: 12px;">
          <span style="display: inline-block; padding: 3px 8px; background: ${priorityColor}; color: #fff; border-radius: 3px; font-weight: 500;">${proposal.priority === 'high' ? '高' : proposal.priority === 'medium' ? '中' : '低'}</span>
        </td>
        <td style="padding: 10px 12px; text-align: center; font-size: 12px;">
          <span style="display: inline-block; padding: 3px 8px; background: ${statusBg}; color: #fff; border-radius: 3px; font-weight: 500; font-size: 11px;">
            ${proposal.approval_status === 'approved' ? '承認済' : proposal.approval_status === 'rejected' ? '却下' : proposal.approval_status === 'in_review' ? '審査中' : '未承認'}
          </span>
        </td>
      `;

      row.addEventListener('click', () => {
        currentSelectedId = proposal.id;
        selectedForBulk.clear();
        showDetail(proposal);
        applyFiltersAndRender();
      });

      tbody.appendChild(row);
    });
  }

  // 詳細表示
  function showDetail(proposal) {
    noSelection.style.display = 'none';
    detailPanel.style.display = 'block';

    container.querySelector('#detail-id').textContent = proposal.proposal_id || '-';
    container.querySelector('#detail-proposer').textContent = proposal.proposer_name || '-';
    container.querySelector('#detail-content').textContent = proposal.proposal_content || '-';
    container.querySelector('#detail-date').textContent = proposal.proposal_date ? new Date(proposal.proposal_date).toLocaleString('ja-JP') : '-';
    container.querySelector('#detail-impact').textContent = proposal.impact_score ? `${proposal.impact_score}/100` : '-';
    container.querySelector('#detail-difficulty').textContent = proposal.implementation_difficulty || '-';
    container.querySelector('#detail-effect').textContent = proposal.expected_effect || '-';

    container.querySelector('#detail-priority').value = proposal.priority || '';
    container.querySelector('#detail-status').value = proposal.approval_status || '';
    container.querySelector('#detail-remarks').value = proposal.remarks || '';
  }

  // 詳細保存
  saveDetailBtn.addEventListener('click', async () => {
    if (!currentSelectedId) return;

    const priority = container.querySelector('#detail-priority').value;
    const status = container.querySelector('#detail-status').value;
    const remarks = container.querySelector('#detail-remarks').value;

    if (!priority || !status) {
      alert('優先度とステータスを選択してください');
      return;
    }

    const updated = await window.aivicApi.update(0, currentSelectedId, {
      priority,
      approval_status: status,
      remarks
    });

    if (updated) {
      alert('保存しました');
      await loadProposals();
      currentSelectedId = null;
      noSelection.style.display = 'flex';
      detailPanel.style.display = 'none';
    }
  });

  cancelDetailBtn.addEventListener('click', () => {
    currentSelectedId = null;
    noSelection.style.display = 'flex';
    detailPanel.style.display = 'none';
  });

  // フィルタ検索
  searchBtn.addEventListener('click', applyFiltersAndRender);

  // 更新
  refreshBtn.addEventListener('click', loadProposals);

  // CSVエクスポート
  exportBtn.addEventListener('click', async () => {
    const proposals = await window.aivicApi.list(0);
    if (!proposals || proposals.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['提案ID', '提案者', '提案内容', '提案日時', '優先度', '承認ステータス', '影響度', '実装難度', '期待効果'];
    const rows = proposals.map(p => [
      p.proposal_id || '',
      p.proposer_name || '',
      p.proposal_content || '',
      p.proposal_date ? new Date(p.proposal_date).toLocaleString('ja-JP') : '',
      p.priority === 'high' ? '高' : p.priority === 'medium' ? '中' : '低',
      p.approval_status === 'approved' ? '承認済' : p.approval_status === 'rejected' ? '却下' : p.approval_status === 'in_review' ? '審査中' : '未承認',
      p.impact_score || '',
      p.implementation_difficulty || '',
      p.expected_effect || ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `proposals_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 一括承認
  bulkApproveBtn.addEventListener('click', () => {
    showConfirm('一括承認', '選択された提案をすべて承認しますか？', async () => {
      const proposals = await window.aivicApi.list(0);
      for (const p of proposals) {
        if (p.approval_status !== 'approved') {
          await window.aivicApi.update(0, p.id, { approval_status: 'approved' });
        }
      }
      alert('承認しました');
      await loadProposals();
    });
  });

  // 一括却下
  bulkRejectBtn.addEventListener('click', () => {
    showConfirm('一括却下', '選択された提案をすべて却下しますか？', async () => {
      const proposals = await window.aivicApi.list(0);
      for (const p of proposals) {
        if (p.approval_status !== 'rejected') {
          await window.aivicApi.update(0, p.id, { approval_status: 'rejected' });
        }
      }
      alert('却下しました');
      await loadProposals();
    });
  });

  // 初期化
  loadProposals();
}

